ker, args=(r, init_file, queue)) for r in range(2)]\n            for p in processes: p.start()\n            for p in processes: p.join(60)\n            for p in processes:\n                self.assertFalse(p.is_alive(), 'DDP worker timed out')\n                self.assertEqual(p.exitcode, 0)\n            gathered_grad, gathered_params = queue.get()\n            self.assertEqual(len(gathered_grad), 2)\n            self.assertEqual(len(gathered_params), 2)\n            self.assertTrue(torch.allclose(torch.tensor(gathered_grad[0]), torch.tensor(gathered_grad[1]), atol=1e-7, rtol=1e-6))\n            self.assertTrue(torch.allclose(torch.tensor(gathered_params[0]), torch.tensor(gathered_params[1]), atol=1e-7, rtol=1e-6))\n\nif __name__ == '__main__': unittest.main()\n",
