bservations = []\n            real_model = trainer.RQVAE\n            class ObservedModel(real_model):\n                def forward(self, *args, **kwargs):\n                    result = super().forward(*args, **kwargs)\n                    observations.append(tuple(float(v.detach()) for v in result))\n                    return result\n            trainer.RQVAE = ObservedModel\n            try:\n                trainer.main()\n            finally:\n                trainer.RQVAE = real_model\n            self.assertTrue(trainer.CHECKPOINT.is_file())\n            self.assertTrue(trainer.OUTPUT_SID.is_file())\n            ckpt = torch.load(trainer.CHECKPOINT, map_location='cpu', weights_only=False)\n            sid = np.load(trainer.OUTPUT_SID)\n            self.assertEqual(ckpt['epoch'], 1)\n            self.assertEqual(ckpt['selection'], 'final_epoch')\n            self.assertTrue(ckpt['state_dict'])\n            self.assertEqual(sid.shape, (len(embeddings), 4))\n            self.assertEqual(len(np.unique(sid, axis=0)), len(embeddings))\n            self.assertTrue(trainer.OUTPUT_JSON.is_file())\n            exported = json.loads(trainer.OUTPUT_JSON.read_text())\n            self.assertEqual(len(exported), len(embeddings))\n            self.assertTrue(observations, 'real trainer forward/loss was not called')\n            for total, reconstruction, balance in observations:\n                self.assertTrue(np.isfinite([total, reconstruction, balance]).all())\n                self.assertAlmostEqual(total, reconstruction + balance, places=4)\n            self.assertEqual(trainer._tokenizer_config().geometry, 'global_sinkhorn')\n            self.assertEqual(trainer._tokenizer_config().curvature, 1.0)\n\nif __name__ == '__main__': unittest.main()\n"
